#include <stddef.h>
typedef struct {
    int active_ua;
    int sleep_ua;
    int active_ms;
    int sleep_ms;
} PowerProfile;

int avg_current_ua(const PowerProfile *p)
{
    if (p == NULL) {
        return -1;
    }
    if (p->active_ua < 0 || p->sleep_ua < 0 ||
        p->active_ms < 0 || p->sleep_ms < 0) {
        return -1;
    }

    long long total_ms = (long long)p->active_ms + (long long)p->sleep_ms;
    if (total_ms == 0) {
        return -1;  /* 周期为 0，平均电流无定义 */
    }

    /* 一个周期内的电荷量（μA·ms）；用 64 位承接，避免 32 位溢出 */
    long long charge = (long long)p->active_ua * (long long)p->active_ms
                     + (long long)p->sleep_ua * (long long)p->sleep_ms;

    /* 整数四舍五入：先加半个周期再整除 */
    return (int)((charge + total_ms / 2) / total_ms);
}
